import{_ as n,o as a,c as s,a5 as t}from"./chunks/framework.DfywBLEo.js";const m=JSON.parse('{"title":"字体图标","description":"","frontmatter":{},"headers":[],"relativePath":"reference/fonticon.md","filePath":"reference/fonticon.md","lastUpdated":1792557099000}'),o={name:"reference/fonticon.md"};function l(r,e,c,p,i,d){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="字体图标" tabindex="-1">字体图标 <a class="header-anchor" href="#字体图标" aria-label="Permalink to &quot;字体图标&quot;">​</a></h1><p>主题使用 <a href="https://www.iconfont.cn/" target="_blank" rel="noreferrer">iconfont</a> 图标库。</p><h2 id="内置图标" tabindex="-1">内置图标 <a class="header-anchor" href="#内置图标" aria-label="Permalink to &quot;内置图标&quot;">​</a></h2><ul><li><a href="https://bndong.github.io/Cnblogs-Theme-SimpleMemory/v2/iconfontDemo/demo_index.html" target="_blank" rel="noreferrer">基本图标预览</a>：用于导航、页脚等位置，初始化时加载 CSS。</li><li><a href="https://bndong.github.io/Cnblogs-Theme-SimpleMemory/v2/iconfontDemo/posts_index.html" target="_blank" rel="noreferrer">文章标题图标预览</a>：用于正文标题前的装饰，开启 <code>articleContent.prefixIcon</code> 后在文章页加载。</li></ul><p>v2.1.3 及以后，内置基本图标使用 <code>simple-memory-</code> 前缀。不同配置字段的写法有所区别：</p><table tabindex="0"><thead><tr><th>位置</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>sidebar.navList</code> 第三个值</td><td><code>icon-github</code></td><td>插件会添加内置前缀，同时保留扩展图标类名</td></tr><tr><td><code>sidebar.customList</code> 的 <code>icon</code></td><td><code>simple-memory-icon-brush_fill</code></td><td>直接输出类名，使用内置图标时要写完整前缀</td></tr><tr><td><code>footer.text.iconFont.icon</code></td><td><code>icon-xl</code></td><td>插件会添加内置前缀</td></tr><tr><td>友链分类的 <code>icon</code></td><td><code>icon-weibiaoti22</code></td><td>插件会添加内置前缀</td></tr></tbody></table><h2 id="扩展图标库" tabindex="-1">扩展图标库 <a class="header-anchor" href="#扩展图标库" aria-label="Permalink to &quot;扩展图标库&quot;">​</a></h2><p>在 iconfont 创建自己的图标库并获取 CSS 地址，方法见<a href="https://www.iconfont.cn/help/detail?helptype=about" target="_blank" rel="noreferrer">官方教程</a>。保留默认的 <code>icon-</code> 类名前缀，然后配置：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki simplememory-plum vp-code" tabindex="0"><code><span class="line"><span style="color:#EEE6F7;">window.</span><span style="color:#F0ADC4;">cnblogsConfig</span><span style="color:#F0ADC4;"> =</span><span style="color:#EEE6F7;"> {</span></span>
<span class="line"><span style="color:#EEE6F7;">  fontIconExtend: </span><span style="color:#D1B4FA;">&#39;https://at.alicdn.com/t/你的图标库.css&#39;</span><span style="color:#EEE6F7;">,</span></span>
<span class="line"><span style="color:#EEE6F7;">  sidebar: {</span></span>
<span class="line"><span style="color:#EEE6F7;">    navList: [</span></span>
<span class="line"><span style="color:#EEE6F7;">      [</span><span style="color:#D1B4FA;">&#39;我的链接&#39;</span><span style="color:#EEE6F7;">, </span><span style="color:#D1B4FA;">&#39;https://example.com/&#39;</span><span style="color:#EEE6F7;">, </span><span style="color:#D1B4FA;">&#39;icon-xxx&#39;</span><span style="color:#EEE6F7;">],</span></span>
<span class="line"><span style="color:#EEE6F7;">    ],</span></span>
<span class="line"><span style="color:#EEE6F7;">  },</span></span>
<span class="line"><span style="color:#EEE6F7;">};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>将地址和 <code>icon-xxx</code> 替换为图标库实际生成的值。扩展图标与内置图标同名时，扩展样式可能覆盖相应图标，建议为自己的图标使用不重复的名称。</p>`,10)])])}const h=n(o,[["render",l]]);export{m as __pageData,h as default};
